arguments.file_text:
@page "/categories"
@page "/categories/{CategoryName}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@(CategoryName ?? "All Categories") — Recipe Community</PageTitle>

@if (string.IsNullOrEmpty(CategoryName))
{
    <h1>All Categories</h1>
    <div class="list-group">
        @foreach (var cat in RecipeService.GetCategories())
        {
            <a href="@($"categories/{cat}")" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                @cat
                <span class="badge bg-primary rounded-pill">@RecipeService.GetByCategory(cat).Count</span>
            </a>
        }
    </div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">All Categories</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    var recipes = RecipeService.GetByCategory(CategoryName);
    if (recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Description</p>
                            <div class="mb-2">
                                <span class="text-warning">
                                    @for (int i = 1; i <= 5; i++)
                                    {
                                        @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                                    }
                                </span>
                                <small class="text-muted">(@recipe.TotalRatings ratings)</small>
                            </div>
                            <a href="@($"recipe/{recipe.Id}")" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? CategoryName { get; set; }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe Not Found") — Recipe Community</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="categories" class="btn btn-primary">Browse Recipes</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">All Categories</a></li>
            <li class="breadcrumb-item"><a href="@($"categories/{recipe.Category}")">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="lead">@recipe.Description</p>

    <StarRating RecipeId="recipe.Id" CurrentAverage="recipe.AverageRating" TotalRatings="recipe.TotalRatings" />

    <hr />

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <h4>Instructions</h4>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services

<div class="d-flex align-items-center gap-2 my-3">
    <span class="fw-bold">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => SubmitRating(star)"
                disabled="@hasRated"
                title="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
            <span class="@(star <= displayRating ? "text-warning" : "text-secondary")"
                  @onmouseover="() => OnHover(star)"
                  @onmouseout="ResetHover">
                @(star <= displayRating ? "★" : "☆")
            </span>
        </button>
    }
    <span class="text-muted ms-2">
        @if (hasRated)
        {
            <span class="text-success">✓ Thanks for rating!</span>
        }
        else
        {
            <span>@CurrentAverage.ToString("0.0") avg (@TotalRatings ratings)</span>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int TotalRatings { get; set; }

    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private int hoveredStar;
    private bool hasRated;
    private int displayRating => hoveredStar > 0 ? hoveredStar : (int)Math.Round(CurrentAverage);

    private void OnHover(int star)
    {
        if (!hasRated)
            hoveredStar = star;
    }

    private void ResetHover() => hoveredStar = 0;

    private void SubmitRating(int stars)
    {
        if (hasRated) return;

        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            TotalRatings = recipe.TotalRatings;
        }
        hasRated = true;
        hoveredStar = 0;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — Recipe Community</PageTitle>

<h1>Submit Your Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (!string.IsNullOrEmpty(successMessage))
{
    <div class="alert alert-success">@successMessage</div>
}

<div class="row">
    <div class="col-md-8">
        <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="submission.Title"
                           placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
                    <option value="">— Select a category —</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat">@cat</option>
                    }
                    <option value="Other">Other</option>
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="6"
                               @bind-Value="submission.Ingredients"
                               placeholder="Enter each ingredient on a new line" />
                <div class="form-text">One ingredient per line.</div>
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="8"
                               @bind-Value="submission.Steps"
                               placeholder="Enter each step on a new line" />
                <div class="form-text">One step per line.</div>
            </div>

            <button type="submit" class="btn btn-success btn-lg"
                    disabled="@(!IsValid)">
                Submit Recipe
            </button>
        </EditForm>
    </div>

    <div class="col-md-4">
        <div class="card bg-light">
            <div class="card-body">
                <h5 class="card-title">Tips</h5>
                <ul class="mb-0">
                    <li>Be specific with measurements</li>
                    <li>List ingredients in order of use</li>
                    <li>Write clear, numbered steps</li>
                    <li>Include cooking temperatures and times</li>
                </ul>
            </div>
        </div>
    </div>
</div>

@code {
    private RecipeSubmission submission = new();
    private string? successMessage;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(submission.Title) &&
        !string.IsNullOrWhiteSpace(submission.Category) &&
        !string.IsNullOrWhiteSpace(submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(submission.Steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;

        var recipe = RecipeService.AddRecipe(submission);
        successMessage = $"\"{recipe.Title}\" has been submitted successfully!";
        submission = new RecipeSubmission();
    }
}

